`timescale 1ps / 1ps

module tb_axi_coefficient_memory();

    parameter integer S_AXI_ID_WIDTH   = 4  ;
    parameter integer S_AXI_DATA_WIDTH = 32 ;
    parameter integer S_AXI_ADDR_WIDTH = 14 ;
    parameter integer FILTER_ORDER     = 256;
    parameter integer FILTER_COUNT     = 24 ;

    logic clk   ;
    logic resetn;
    // external control for reading coefficients
    logic [S_AXI_ADDR_WIDTH-1:0] addrb = '{default:0};
    logic                        enb   = 1'b0        ;
    logic [S_AXI_DATA_WIDTH-1:0] doutb = '{default:0};
    // Coefficient AXI loading bus
    logic [      S_AXI_ID_WIDTH-1:0] s_axi_awid     = '{default:0};
    logic [    S_AXI_ADDR_WIDTH-1:0] s_axi_awaddr   = '{default:0};
    logic [                     7:0] s_axi_awlen    = '{default:0};
    logic [                     2:0] s_axi_awsize   = '{default:0};
    logic [                     1:0] s_axi_awburst  = '{default:0};
    logic                            s_axi_awlock   = 1'b0        ;
    logic [                     3:0] s_axi_awcache  = '{default:0};
    logic [                     2:0] s_axi_awprot   = '{default:0};
    logic [                     3:0] s_axi_awqos    = '{default:0};
    logic [                     3:0] s_axi_awregion = '{default:0};
    logic                            s_axi_awvalid  = 1'b0        ;
    logic                            s_axi_awready                ;
    logic [    S_AXI_DATA_WIDTH-1:0] s_axi_wdata    = '{default:0};
    logic [(S_AXI_DATA_WIDTH/8)-1:0] s_axi_wstrb    = '{default:0};
    logic                            s_axi_wlast    = 1'b0        ;
    logic                            s_axi_wvalid   = 1'b0        ;
    logic                            s_axi_wready                 ;
    logic [      S_AXI_ID_WIDTH-1:0] s_axi_bid                    ;
    logic [                     1:0] s_axi_bresp                  ;
    logic                            s_axi_bvalid                 ;
    logic                            s_axi_bready   = 1'b0        ;
    logic [      S_AXI_ID_WIDTH-1:0] s_axi_arid     = '{default:0};
    logic [    S_AXI_ADDR_WIDTH-1:0] s_axi_araddr   = '{default:0};
    logic [                     7:0] s_axi_arlen    = '{default:0};
    logic [                     2:0] s_axi_arsize   = '{default:0};
    logic [                     1:0] s_axi_arburst  = '{default:0};
    logic                            s_axi_arlock   = 1'b0        ;
    logic [                     3:0] s_axi_arcache  = '{default:0};
    logic [                     2:0] s_axi_arprot   = '{default:0};
    logic [                     3:0] s_axi_arqos    = '{default:0};
    logic [                     3:0] s_axi_arregion = '{default:0};
    logic                            s_axi_arvalid  = 1'b0        ;
    logic                            s_axi_arready                ;
    logic [      S_AXI_ID_WIDTH-1:0] s_axi_rid                    ;
    logic [    S_AXI_DATA_WIDTH-1:0] s_axi_rdata                  ;
    logic [                     1:0] s_axi_rresp                  ;
    logic                            s_axi_rlast                  ;
    logic                            s_axi_rvalid                 ;
    logic                            s_axi_rready   = 1'b0        ;

    integer index = 0;

    initial begin 
        clk = 1'b0;
        forever 
        #2500 clk = ~clk;
    end 

    always_ff @(posedge clk) begin 
        index <= index + 1;
    end 

    always_ff @(posedge clk) begin 
        if (index < 10) begin 
            resetn <= 1'b0;
        end else begin 
            resetn <= 1'b1;
        end 
    end 

    always_comb s_axi_awid = 4'hF;
    always_comb s_axi_awlen = 8'h7F;
    always_comb s_axi_awsize = 3'b010;
    always_comb s_axi_awburst = 2'b01;
    always_comb s_axi_wstrb = 4'hF;

    axi_coefficient_memory #(
        .S_AXI_ID_WIDTH  (S_AXI_ID_WIDTH  ),
        .S_AXI_DATA_WIDTH(S_AXI_DATA_WIDTH),
        .S_AXI_ADDR_WIDTH(S_AXI_ADDR_WIDTH),
        .FILTER_ORDER    (FILTER_ORDER    ),
        .FILTER_COUNT    (FILTER_COUNT    )
    ) axi_coefficient_memory_inst (
        .i_clk         (clk           ),
        .i_resetn      (resetn        ),
        // external control
        .addrb         (addrb         ),
        .enb           (enb           ),
        .doutb         (doutb         ),
        // Coefficient AXI loading bus
        .S_AXI_ACLK    (clk           ),
        .S_AXI_ARESETN (resetn        ),
        .S_AXI_AWID    (s_axi_awid    ),
        .S_AXI_AWADDR  (s_axi_awaddr  ),
        .S_AXI_AWLEN   (s_axi_awlen   ),
        .S_AXI_AWSIZE  (s_axi_awsize  ),
        .S_AXI_AWBURST (s_axi_awburst ),
        .S_AXI_AWLOCK  (s_axi_awlock  ),
        .S_AXI_AWCACHE (s_axi_awcache ),
        .S_AXI_AWPROT  (s_axi_awprot  ),
        .S_AXI_AWQOS   (s_axi_awqos   ),
        .S_AXI_AWREGION(s_axi_awregion),
        .S_AXI_AWVALID (s_axi_awvalid ),
        .S_AXI_AWREADY (s_axi_awready ),
        .S_AXI_WDATA   (s_axi_wdata   ),
        .S_AXI_WSTRB   (s_axi_wstrb   ),
        .S_AXI_WLAST   (s_axi_wlast   ),
        .S_AXI_WVALID  (s_axi_wvalid  ),
        .S_AXI_WREADY  (s_axi_wready  ),
        .S_AXI_BID     (s_axi_bid     ),
        .S_AXI_BRESP   (s_axi_bresp   ),
        .S_AXI_BVALID  (s_axi_bvalid  ),
        .S_AXI_BREADY  (s_axi_bready  ),
        .S_AXI_ARID    (s_axi_arid    ),
        .S_AXI_ARADDR  (s_axi_araddr  ),
        .S_AXI_ARLEN   (s_axi_arlen   ),
        .S_AXI_ARSIZE  (s_axi_arsize  ),
        .S_AXI_ARBURST (s_axi_arburst ),
        .S_AXI_ARLOCK  (s_axi_arlock  ),
        .S_AXI_ARCACHE (s_axi_arcache ),
        .S_AXI_ARPROT  (s_axi_arprot  ),
        .S_AXI_ARQOS   (s_axi_arqos   ),
        .S_AXI_ARREGION(s_axi_arregion),
        .S_AXI_ARVALID (s_axi_arvalid ),
        .S_AXI_ARREADY (s_axi_arready ),
        .S_AXI_RID     (s_axi_rid     ),
        .S_AXI_RDATA   (s_axi_rdata   ),
        .S_AXI_RRESP   (s_axi_rresp   ),
        .S_AXI_RLAST   (s_axi_rlast   ),
        .S_AXI_RVALID  (s_axi_rvalid  ),
        .S_AXI_RREADY  (s_axi_rready  )
    );



    always_ff @(posedge clk) begin
        case (index)
            // #0 
            1000    : begin s_axi_awaddr <= 14'h0000; s_axi_awvalid <= 1'b1; s_axi_wdata <= 32'h00000139; s_axi_wvalid <= 1'b1; s_axi_wlast <= 1'b0; s_axi_bready <= 1'b0; end
            1001    : begin s_axi_awaddr <= 14'h0000; s_axi_awvalid <= 1'b1; s_axi_wdata <= 32'h00000139; s_axi_wvalid <= 1'b1; s_axi_wlast <= 1'b0; s_axi_bready <= 1'b0; end
            1002    : begin s_axi_awaddr <= 14'h0000; s_axi_awvalid <= 1'b1; s_axi_wdata <= 32'h00000139; s_axi_wvalid <= 1'b1; s_axi_wlast <= 1'b0; s_axi_bready <= 1'b0; end
            1003    : begin s_axi_awaddr <= 14'h0000; s_axi_awvalid <= 1'b0; s_axi_wdata <= 32'h00000139; s_axi_wvalid <= 1'b1; s_axi_wlast <= 1'b0; s_axi_bready <= 1'b0; end
            1004    : begin s_axi_awaddr <= 14'h0000; s_axi_awvalid <= 1'b0; s_axi_wdata <= 32'h00000650; s_axi_wvalid <= 1'b1; s_axi_wlast <= 1'b0; s_axi_bready <= 1'b0; end
            1005    : begin s_axi_awaddr <= 14'h0000; s_axi_awvalid <= 1'b0; s_axi_wdata <= 32'h00000067; s_axi_wvalid <= 1'b1; s_axi_wlast <= 1'b0; s_axi_bready <= 1'b0; end
            1006    : begin s_axi_awaddr <= 14'h0000; s_axi_awvalid <= 1'b0; s_axi_wdata <= 32'h000001a7; s_axi_wvalid <= 1'b1; s_axi_wlast <= 1'b0; s_axi_bready <= 1'b0; end
            1007    : begin s_axi_awaddr <= 14'h0000; s_axi_awvalid <= 1'b0; s_axi_wdata <= 32'h00000177; s_axi_wvalid <= 1'b1; s_axi_wlast <= 1'b0; s_axi_bready <= 1'b0; end
            1008    : begin s_axi_awaddr <= 14'h0000; s_axi_awvalid <= 1'b0; s_axi_wdata <= 32'h00000182; s_axi_wvalid <= 1'b1; s_axi_wlast <= 1'b0; s_axi_bready <= 1'b0; end
